using esham.BLL.DTOs.Courses;
namespace esham.BLL.Interfaces;

// Keys are opaque, generated by storage, never supplied as filesystem paths by clients.
public interface IMediaStorage
{
    Task<StoredMediaFile> SaveAsync(Stream input, string contentType, CancellationToken ct);
    Task<Stream?> OpenAsync(string key, CancellationToken ct);
    Task DeleteAsync(string key, CancellationToken ct);
}
